import { USERS, expect, test } from "../../fixtures";

test.describe("AUTH-01 sign in", () => {
  test("successful sign-in returns a session", { tag: "@AUTH-01" }, async ({ request }) => {
    // Act
    const response = await request.post("/api/auth/login", {
      data: { email: USERS.member, password: "demo-password" },
    });

    // Assert
    expect(response.status()).toBe(200);

    const body = (await response.json()) as { access_token?: unknown };
    expect(typeof body.access_token).toBe("string");
    expect((body.access_token as string).length).toBeGreaterThan(0);

    const setCookies = response
      .headersArray()
      .filter((h) => h.name.toLowerCase() === "set-cookie")
      .map((h) => h.value);
    const session = setCookies.find((value) => value.startsWith("session="));
    expect(session, "a session cookie is set").toBeDefined();
    expect(session!.toLowerCase()).toContain("httponly");
  });
});
